import java.util.*;

class Solution {
  private static final int INF = 1_000_000;
  private final Map<String, Integer> memo = new HashMap<>();

  public int findMinStep(String board, String hand) {
    char[] h = hand.toCharArray();
    Arrays.sort(h);
    int result = dfs(board, new String(h));
    return result >= INF ? -1 : result;
  }

  // tries every ball at every useful position: next to the same colour, or splitting a pair of another colour
  private int dfs(String board, String hand) {
    if (board.isEmpty()) return 0;
    if (hand.isEmpty()) return INF;
    String key = board + "#" + hand;
    Integer cached = memo.get(key);
    if (cached != null) return cached;
    int best = INF;
    for (int j = 0; j < hand.length(); j++) {
      if (j > 0 && hand.charAt(j) == hand.charAt(j - 1)) continue;
      char c = hand.charAt(j);
      String rest = hand.substring(0, j) + hand.substring(j + 1);
      for (int i = 0; i <= board.length(); i++) {
        if (i > 0 && board.charAt(i - 1) == c) continue; // same as inserting before that run
        boolean sameColour = i < board.length() && board.charAt(i) == c;
        boolean splitsPair =
            i > 0 && i < board.length() && board.charAt(i - 1) == board.charAt(i) && board.charAt(i) != c;
        if (!sameColour && !splitsPair) continue;
        int r = dfs(shrink(board.substring(0, i) + c + board.substring(i)), rest);
        if (r < INF) best = Math.min(best, r + 1);
      }
    }
    memo.put(key, best);
    return best;
  }

  private String shrink(String s) {
    for (int i = 0; i < s.length(); ) {
      int j = i;
      while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
      if (j - i >= 3) return shrink(s.substring(0, i) + s.substring(j));
      i = j;
    }
    return s;
  }
}
